window.PRM_DATA=window.PRM_DATA||{shards:{}};PRM_DATA.pdfs=[{"src": "PDF", "file": "260927-Doa-dan-Dzikir-1.pdf", "title": "Do’a dan Dzikir (1)", "date": "2026-09-27", "ahad": "Ahad, 27 September 2026 / 15 Rabiiul Akhir 1448", "no": "2278/2318/IA", "pages": 12, "size": 251912, "uploadedAt": "2026-11-01T15:51:22.413Z", "v": 1, "blocks": [["p", "Ahad, 27 September 2026 / 15 Rabiiul Akhir 1448", 1], ["p", "Brosur No.: 2278/2318/IA", 1], ["h", "DO’A DAN DZIKIR (1)", 1], ["p", "Doa merupakan bagian penting dalam kehidupan seorang muslim. Doa bukan sekadar rangkaian kalimat yang diucapkan ketika seseorang sedang menghadapi kesulitan, tetapi merupakan bentuk ibadah, penghambaan, ketundukan, dan pengakuan bahwa manusia senantiasa membutuhkan pertolongan Allah. Dalam keadaan lapang maupun sempit, sehat maupun sakit, berhasil maupun sedang menghadapi persoalan, seorang mukmin membutuhkan doa.", 1], ["p", "Allah SWT berfirman:", 1], ["a", "وَقَال َ رَبُّكُم ُ ادْعُوْن ِْْٓ اَسْتَجِب ْ لَكُمْ", 1], ["p", "“Dan Tuhanmu berfirman: “Berdoalah kepada-Ku, niscaya akan Aku perkenankan bagimu.” [QS. Al Mukmin: 60]", 1], ["p", "Ayat tersebut menunjukkan betapa pentingnya doa dalam kehidupan seorang hamba. Doa mendidik kita untuk tidak merasa cukup dengan kekuatan diri sendiri. Doa menumbuhkan keyakinan bahwa di balik segala usaha manusia ada kekuasaan Allah, dan bahwa pertolongan yang sejati hanya berasal dari-Nya.", 1], ["p", "Di tengah kehidupan yang semakin kompleks, manusia sering dihadapkan pada berbagai persoalan, kesibukan, kekhawatiran, dan berbagai keadaan yang tidak selalu dapat dikendalikan. Dalam kondisi seperti itu, doa menjadi kebutuhan yang tidak boleh diabaikan. Sayangnya, tidak sedikit di antara kita yang baru mengingat doa ketika berada dalam kesulitan, sementara ketika mendapatkan kelapangan", 1], ["p", "justru melupakannya. Padahal, seorang muslim diperintahkan untuk senantiasa mengingat Allah dalam setiap keadaan.", 2], ["p", "Rasulullah SAW juga mengajarkan berbagai doa dalam banyak kesempatan. Hal ini menunjukkan bahwa doa seharusnya menjadi bagian dari kehidupan, bukan sekadar pelengkap kehidupan.", 2], ["h", "1. Keutamaan dzikir kepada Allah", 2], ["p", "Dzikir kepada Allah bukan sekadar ucapan yang dilafalkan oleh lisan, tetapi merupakan amalan yang memiliki pengaruh besar bagi kehidupan seorang muslim. Dengan berdzikir, seorang hamba senantiasa mengingat Allah, hatinya menjadi tenteram, semakin dekat kepada-Nya, memperoleh ampunan dan rahmat, serta mendapatkan ketenangan dan penjagaan para malaikat. Dzikir juga menjadi tanda hidupnya hati dan merupakan amalan yang ringan untuk dilakukan kapan saja dan di mana saja. Karena itu, seorang muslim hendaknya membiasakan lisannya untuk senantiasa berdzikir kepada Allah.", 2], ["p", "Firman Allah SWT :", 2], ["a", "فَاذْكُرُوْن ِْ اَذْكُرْكُم ْ وَاشْكُرُوْا ِِلِْ و ََلَ تَكْفُرُوْن . البقرة : 152", 2], ["p", "Maka ingatlah kalian kepada-Ku niscaya Aku ingat (pula) kepada kalian, dan bersyukurlah kalian kepada-Ku, dan janganlah kalian mengingkari (ni’mat)-Ku. [QS. Al-Baqarah 152]", 2], ["a", ")41( كَث ِْيًْاذِكْرًا َللا آمَنُوا اذْكُرُوا الَّذِيْنَ ُّهَاٰيَْٓٓي 42-41 اَلحزاب: . )42( ًْلً وَّاَصِي وَسَبِحُوْه ُ بُكْرَةً", 2], ["p", "41. Hai orang-orang yang beriman, berdzikirlah (dengan menyebut nama) Allah, dzikir yang sebanyak-banyaknya.", 2], ["p", "42. Dan bertasbihlah kepada-Nya di waktu pagi dan petang. [QS Al-Ahzaab :41-42]", 2], ["a", "الَّذِيْن َ آمَنُوْا وَتَطْمَىِٕن ُّ ق ُِٓلُو ُْبُُم ْ بِذِكْر ِ الل ا ََُّلَ بِذِكْر ِ الل ِٓ تَطْمَىِٕن", 2], ["a", "28 الرعد : .الْقُلُوْبُ", 3], ["p", "(yaitu) orang-orang yang beriman dan hati mereka menjadi tenteram dengan mengingat Allah. Ingatlah, hanya dengan mengingat Allah-lah hati menjadi tenteram. [QS. Ar-Ra’du : 28]", 3], ["a", "وَاص ْف ِْ كَفْع م ََْ َََ الَّذِيْن َ يَدْعُوْن َ ر َُبَُّم ْ اِل ََْدٓوة ِ وَالْدَو َِِ يُرِيْدُوْن َ و ْي ي وَجْه و ََلَ تَدْد ُ عَيْن عَن َْْٓهُم تُرِيْد ُ َِيْنَة َ الَْيٓوة ِ الدُّكْيَا و ََلَ تُط ْمَن َِْ َ و و اَغْفَلْنَا قَلْب عَن ْ ذِكْر َِنَ وَاتَّب َََ هَوٓى ُ و ََكَان اَمْرُه فُرُطًا . الكهف : 28", 3], ["p", "Dan bershabarlah dirimu bersama-sama dengan orang-orang yang menyeru Tuhannya di pagi dan senja hari dengan mengharap keridlaan-Nya; dan janganlah kedua matamu berpaling dari mereka (karena) mengharapkan perhiasan kehidupan dunia ini; dan janganlah kamu mengikuti orang yang hatinya telah Kami lalaikan dari mengingati Kami, serta menuruti hawa nafsunya dan adalah keadaannya itu melewati batas. [QS.Al-Kahfi : 28]", 3], ["p", "Hadits-hadits Nabi SAW:", 3], ["a", "ِْعَن ْ اَب هُرَيْرَة َ عَن ْ رَسُوْل ِ للا ِ ملسو هيلع هللا ىلص اَك َّ ُ قَالَ: قَال َ للاُ عَز َّ وَجَلَّ: ا ََنَ عِنْد َ ظَن ِ عَبْدِي ْ ب ْ وَا ََنَ مَد َ ُ حَيْث ُ يَذْكُرُنِْ، وَللا ِ لل َ ُٓ اَفْرَح ُ بِت َِوْبَة عَبْدِه ِ مِن ْ اَحَدِكُم ْ َيَِد ُ ضَالَّت َ ُ اِلْف ًَلَةِ. وَمَن ْ تَقَرَّب َ ا َِلََّ شِفًْا ت َُقَرَّبْت اِلَي ِ ْ ذِرَاعًا، وَمَن ْ تَقَرَّب َ ا َِلََّ ذِرَاعًا تَقَرَّبْت ُ اِلَي ْ ِ اَعًا، وَاِذَا اَقْبَل َ ا َََِّل 1 رقم 2102 :4 . معلمَلْت ُ اِلَي ْ ِ اُهَرْوِل ُ ْبَيَْوِى اَق", 3], ["p", "Dari Abu Hurairah, dari Rasulullah SAW, beliau bersabda : \"Allah 'Azza wa Jalla berfirman : \"Aku menurut persangkaan hamba-Ku", 3], ["p", "kepada-Ku, dan Aku selalu bersamanya dimana saja ia mengingatku\". Rasulullah SAW bersabda : \"Demi Allah, sesungguhnya Allah lebih senang kepada taubat hamba-Nya daripada seseorang diantara kalian mendapatkan kembali barang-barangnya yang hilang di perjalanan di padang pasir\". Allah berfirman : \"Barangsiapa yang mendekat kepadaku sejengkal, Aku akan mendekat kepadanya sehasta. Dan barangsiapa mendekat kepada-Ku sehasta, Aku akan mendekat kepadanya sedepa. Dan apabila ia mendekat kepadaku dengan berjalan, Aku akan mendekat kepadanya dengan berlari\". [HR. Muslim juz 4, hal. 2102 , no.1 ]", 4], ["a", "ِْعَن ْ اَب هُرَيْرَةَ رَض ِ َ للا ُ عَن ْ ُ قَالَ: قَال َ الن َِّبُِّ ملسو هيلع هللا ىلص: يَقُوْل ُ للاُ تَدَا َلَ: ا ََنَ عِنْد َ ظَن ِ عَبْدِي ْ ب ِْ وَا ََنَ مَد َ ُ اِذَا ذَكَرَنِْ. فَاِن ْ ذَكَرَن ِِْف ِْ كَفْع ِ ِ ذَكَرْت ِفِْ ك ُ َُفْع ِ ْ، وَاِن ْ ذَكَرَن ِفِْ م ِْ ََلٍَ ذَكَرْت ِفِْ م ُ ُ ٍََل خ ٍَْْي َ مِنْهُمْ. وَاِن ْ تَقَرَّب َ ا ِِلََّ بِوِف ٍْ تَقَرَّبْت ُ اِلَي ْ ِ ذِرَاعًا. وَاِن ْ تَقَرَّب َ ا ِِلََّ ذِرَاعًا تَقَرَّبْت ُ اِلَي ْ ِ اَعًا. وَاِن ْ ا ََتَن ِْ َيَْو اَت ْ َِيْت ُ ُ هَرْوَلَة. البخارى 8: 171", 4], ["p", "Dari Abu Hurairah RA, ia berkata : Nabi SAW bersabda : \"Allah Ta'aalaa berfirman : \"Aku menurut persangkaan hamba-Ku terhadap-Ku, dan Aku besertanya apabila ia mengingat-Ku. Maka jika ia mengingat-Ku di hatinya, Aku pun mengingatnya pada diri-Ku. Jika ia mengingat (menyebut)-Ku pada sekumpulan orang, maka Aku menyebutnya dalam sekumpulan yang lebih baik dari pada mereka. Dan jika ia mendekat kepada-Ku sejengkal, maka Aku akan mendekat kepadanya sehasta. Jika ia mendekat kepada-Ku sehasta, maka Aku akan mendekat kepadanya sedepa. Dan jika ia datang kepada-Ku dengan berjalan, maka Aku akan datang kepadanya dengan berlari.\" [HR. Bukhari juz 8, hal. 171]", 4], ["a", "عَن اَب هُرَيْرَةَ َقَال ِ: قَال َ رَسُوْل ُ للا ملسو هيلع هللا ىلص اِذَا مَرَر ِبِر ِٰيَض ِا ْلَْنَّة ُُْْت ِْ ْ", 4], ["a", "فَارْتَدُوْا. قُلْتُ: ٰيَ رَسُوْل َ للاِ، وَمَا ر ِٰيَض ُ ا ْلَْنَّةِ؟ قَالَ: اَلْمَعَاجِدُ. قُلْتُ: وَمَا الرَّت َُْ ٰيَ رَسُوْل َ للاِ؟ قَالَ:سُبْحَان َ للا ِ وَالَْمْد ِٓ ِلل و ََلَاِل َ ٓ ُ ، هذا حديث غريب 3576 رقم : 193 :5 الرتمذي . ََُِلَّ للا ُ وَللا ُ اَكْف ا", 5], ["p", "Dari Abu Hurairah, ia berkata: Rasulullah SAW bersabda : \"Apabila kalian melewati taman-taman surga, maka merumputlah!” Aku bertanya : ”Ya Rasulullah apa taman-taman surga itu? Rasulullah SAW menjawab : \"Masjid-masjid.\" Aku bertanya lagi : “Lalu apa rumputnya ya Rasulullah? Beliau bersabda : \"Subhaanallooh, wal hamdu lillaah, wa laa ilaaha illallooh, walloohu akbar” (Maha Suci Allah, segala puji bagi Allah, tidak ada tuhan selain Allah, dan Allah Maha Besar). [HR. Tirmidzi juz 5 hal 193 no 3576, ini hadits gharib]", 5], ["a", "عَن ْ اَكَس ِ بْن ِ مَال ٍِِْ اَن َّ رَسُوْل َ للا ملسو هيلع هللا ىلص ِقَالَ: اِذَا مَرَر ُْتُْ بِر ِٰيَض ِ ا ْلَْنَّة : 5 الرتمذى .َدُوْا. قَالُوْا: وَمَا ر ِٰيَض ُ ا ْلَْنَّة ِ ؟ قَال َ : حِلَق ُ الذِكْر ِ فَارْت ، هذا حديث حعن غريب 3577 رقم 194", 5], ["p", "Dari Anas bin Maalik, bahwasanya Rasulullah SAW bersabda : “Apabila kalian melewati taman-taman surga, maka merumputlah (berhentilah).” Para shahabat bertanya : “ (Ya Rasulullah), apa taman-taman surga itu ?” Beliau bersabda : “Kelompok-kelompok dzikir.” [HR. Tirmidzi juz 5 hal 194 no 3577, ini hadits hasan gharib]", 5], ["p", "Keterangan :", 5], ["p", "Yang termasuk taman-taman surga di dunia ini adalah masjid-masjid, majlis-majlis dzikir, dan majlis-masjlis ilmu yang mengkaji Al-Qur’an dan As-sunnah.", 5], ["a", "ْعَن ِْاَب هُرَيْرَةَ ِ ِعَن ِ النَّب ملسو هيلع هللا ىلص قَالَ: َّاِن لل ِ ِٓ ت ََبَارَك وَتَدَا َلَ م ًَلَئِكَةً", 5], ["a", "سَيَّارَة ً فُض ًُلً يَتَب ََّدُوْن َمََالِس الذِكْرِ. فَاِذَا وَجَدُوْا َمَْلِعًا فِي ٌْ ِ ذِكْر َ قَدَدُوْا مَدَهُم ْ وَحَف َّ بَدْضُهُم ْ بَدْضًا اَِجْنِحَتِهِم ْ ح ََّتَّ يَ مْلَئُوْا مَا بَيْن َْهُم وَب َْيَْ العَّمَاء ِ الدُّكْيَا. فَاِذَا تَفَرَّقُوْا عَرَجُوْا وَصَدِدُوْا ا َِلَ العَّمَاءِ. ق َالَ: فَيَعْأَلُ هُم ُ للا ُ عَز َّ وَجَل َّ وَهُو َ اَعْلَم ُ بِ هِمْ: مِن ْ اَيْن َ جِئْتُمْ؟ فَيَقُوْلُوْنَ: جِئْنَا مِن ْ عِنْد ِ عِبَاد ٍ ل ََْ ِفِ ا َلَْرْض ِ يُعَبِحُوْك ََْ وَيُكَفُِوْك ََْ وَيُهَلِلُوْك ََْ و ََيَْمَدُوْك ََْ وَيَعْأَلُوْك ََْ. قَالَ: وَمَاذَا ي َعْأَلُوْنِْ؟ قَالُوْا: يَعْأَلُوْك جَن َََّْت ََْ. قَالَ: وَهَل ْ رَأَوْا جَن َِّتِْ؟ قَالُوْا: َلَ اَي ْ رَبِ. قَالَ: فَكَيْف َ لَو ْ رَأَوْا جَن َِّتِْ. قَالُوْا: وَيَعْتَج ِْيُْوْك ََْ. قَالَ: وَمِم َّ يَعْتَج ِْيُْوْك َِنِْ؟ قَالُوْا: مِن ْ َنَرِك ََ ٰيَ رَبِ. قَال: وَهَل ْ رَأَوْا َنَرِيْ؟ قَالُوْا: َلَ. قَالَ: فَكَيْف َ لَو ْ رَأَوْا َنَرِيْ. قَالُوْا: وَيَعْت ََْفِرُوْك ََْ. قَال َ فَي َُقُوْلُ: قَد ْ غَفَرْت لَ هُم ْ فَاَعْطَيْتُهُم ْ مَا سَأَلُوْا وَاَجَر ُْتُُم ْ مِ مَّا اسْتَجَارُوْا. قَال َ فَيَقُوْلُوْنَ: ْرَب ِ فِيْهِم ف ًُلَن ٌ عَبْد ٌ خَطَّاءٌ، ا َِّنََّا مَر َّ فَجَلَس َ مَدَهُمْ. قَال َ فَيَقُوْلُ: 25 رقم 2069 :4 معلم ُ َلَ يَوْقَى بِ هِم ْ جَلِيْعُهُمْ. وَل َ ُ غَفَرْتُ، هُم ُ الْقَوْم", 6], ["p", "Dari Abu Hurairah, dari Nabi SAW, beliau besabda : \"Sesungguhnya Allah Yang Maha Berkah lagi Maha Tinggi mempunyai malaikat-malaikat yang selalu berkeliling, yang jumlah mereka terus bertambah, mereka senantiasa mengamati majlis-majlis dzikir. Apabila mereka", 6], ["p", "mendapati majlis dzikir, mereka ikut duduk bersama orang-orang itu, mereka membentangkan sayapnya sebagian mereka dengan sebagian yang lain sehingga memenuhi antara mereka dan langit dunia. Apabila orang-orang yang hadir pada majlis dzikir tersebut sudah selesai dan berpisah, maka para malaikat itu lalu naik ke atas sampai ke langit. Lalu Allah 'Azza wa Jalla bertanya kepada mereka, sedangkan Dia lebih tahu daripada mereka : \"Dari mana kalian ?\". Para malaikat itu menjawab : \"Kami datang dari sisi hamba-hamba-Mu di bumi, mereka itu bertasbih, bertakbir, bertahlil, bertahmid kepada-Mu, dan memohon kepada-Mu\". Allah berfirman : \"Apa yang mereka minta kepada-Ku ?\". Para malaikat itu menjawab : \"Mereka itu memohon surga kepada-Mu\". Allah bertanya : \"Apakah mereka itu pernah melihat surga-Ku ?\". Para malaikat menjawab : \"Belum pernah, wahai Tuhanku\". Allah berfirman : \"Betapa seandainya mereka itu pernah melihat surga-Ku\". Para malaikat berkata : \"Dan mereka itu memohon perlindungan kepada-Mu\". Allah bertanya : \"Dari apa mereka itu memohon perlindungan kepada-Ku ?\". Para malaikat menjawab : \"Dari neraka-Mu, wahai Tuhanku\". Allah bertanya : \"Apakah mereka itu pernah melihat neraka-Ku ?\". Para malaikat menjawab : \"Belum pernah, (wahai Tuhanku)\". Allah berfirman : \"Betapa seandainya mereka itu pernah melihat neraka-Ku\". Para malaikat berkata : \"Dan mereka itu memohon ampun kepada-Mu.” Allah befirman : ''Sungguh Aku telah mengampuni mereka itu , dan Aku berikan apa yang mereka minta, dan Aku berikan perlindungan dari apa yang mereka meminta perlindungan\". Para malaikat itu berkata : \"Wahai Tuhanku, diantara mereka itu ada si fulan, yaitu seorang hamba yang banyak berbuat dosa. Sesungguhnya dia hanya lewat, lalu ikut bergabung duduk bersama mereka\". Allah berfirman : \"Dan baginya Aku telah mengampuni. Mereka itu adalah kaum yang tidak akan celaka teman duduk mereka.\" [HR. Muslim juz 4, hal. 2069 no 25]", 7], ["a", "عَن اَب هُرَيْرَة َ قَالَ: قَال ُرَسُوْل ِللا ملسو هيلع هللا ىلص َّاِن ِٓ ِلل م ًَلَئِكَة يَطُوْف َُوْن ِفِ ً ِْ ْ الطُّرُق ِ يَلْتَمِعُوْن َ اَهْل َ الذِكْرِ. فَاِذَا وَجَدُوْا قَوْمًا يَذْكُرُوْن َ للا َ تَنَادَوْا:", 7], ["a", "هَلُمُّوْا ا َِلَ حَاجَتِكُمْ. قَالَ: فَيَحُفُّو َْنَُم ْ اَِجْنِحَتِهِم ْ ا َِلَ العَّمَاء ِ الدُّكْيَا. قَالَ: فَيَعْأ َُلُُم ْ ر َُبُُّم ْ عَز َّ وَجَل َّ وَهُو َ اَعْلَم ُ مِنْهُمْ: مَا يَقُوْل ُ عِبَادِيْ؟ قَالُوْا: يَقُوْلُوْن َ يُعَبِحُوْك ََْ وَيُكَفُِوْك َو ََْ َيَْمَدُوْك ََْ و ََيَُجِدُوْك َََْ. قَال فَيَقُوْلُ: هَل ْ رَأَوْنِْ؟ قَال َ فَيَقُوْلُوْنَ: َلَ، وَللاِ، مَا رَأَوْكَ. قَال َ فَيَقُوْلُ: كَيْف َ لَو ْ رَأَوْنِْ؟ قَال َ يَقُوْلُوْنَ: لَو ْ رَأَوْكَ كَاكُوْا اَشَد َّ ل َََّْ عِبَادَة ً وَاَشَد ل َََْ َتَْجِيْدًا واَكْثَر َ ل ََْ تَعْبِيْحًا. قَال َ يَقُوْلُ: فَمَا يَعْأَلُوْنِْ؟ قَالَ: يَعْأَلُوْك ََْ ا ْلَْنَّةَ. قَال َ يَقُوْلُ: وَهَل ْ رَأَوْهَا؟ قَال َ يَقُوْلُوْنَ: َلَ، وَللا َٰي ِ رَبِ، مَا رَأَوْهَا. قَال َ يَقُوْلُ: فَكَيْف َ لَو ْ ا ََنَُّم ْ رَأَوْهَا؟ قَال َ يَقُوْل ُ ْوْنَ: لَو ا ََنَُّم ْ رَأَوْهَاكَاكُوْا اَشَد َّ عَلَيْهَا حِرْصًا وَاَشَد َّ ُلََا طَلَبًا وَاَعْظَم َ فِيْهَا رَغْبَةً. قَالَ: فَمِم َّ يَتَدَوَّذُوْنَ؟ قَال َ يَقُوْلُوْنَ: مِن َ النَّارِ. قَال َ ي َْقُوْلُ: وَهَل رَأَوْهَا؟ قَال َ يَقُوْلُوْنَ: ََلَ، وَللاِ، ما رَأَوْهَا. قَال َ ي َْقُوْلُ: فَكَيْف َ لَو رَأَوْهَا؟ قَال َ يَقُوْلُوْنَ: لَو ْ رَأَوْهَاكَاكُوْا اَشَد َّ مِنْهَا فِرَارًا وَاَشَد َّ ُلََا َمََافَةً. قَال َ فَيَقُوْلُ: فَاُشْهِدُكُم ْ اَن ِْ قَد ْ غَفَرْت ُ ُلَُمْ. قَالَ: يَقُوْل ُ مَل َمِن ٌَْ ِالْم ًَلَئِكَة: فِيْهِم ْ ف ًُلَن ٌ لَيْس َ مِنْهُم ْ ا َِّنََّا جَاء َ لَِاجَةٍ. قَالَ: هُم ُ ا ْلُْلَعَاء ُ", 8], ["a", "168 : 7 البخارى ُبِِم ْ جَلِيْعُهُمْ. َلَ يَوْقَى", 9], ["p", "Dari Abu Hurairah, ia berkata: Rasulullah SAW bersabda: \"Sesungguhnya Allah mempunyai para malaikat yang selalu berkeliling di jalan-jalan mencari majlis-majlis dzikir. Apabila mereka mendapati suatu kaum yang berdzikir kepada Allah, lalu mereka memanggil teman-temannya seraya berkata : “Kemarilah kepada apa yang kalian cari!”. Lalu mereka pun datang dan menaungi kaum tersebut dengan sayapnya hingga sampai ke langit dunia. Maka Tuhan mereka 'Azza wa jalla bertanya kepada para malaikat tersebut (padahal Allah lebih tahu daripada mereka): “Apa yang dikatakan oleh hamba-Ku?” Para malaikat menjawab : “Mereka mensucikan Engkau, membesarkan Engkau, memuji Engkau, dan mengagungkan Engkau\". Allah bertanya : ”Apakah mereka pernah melihat-Ku?” Para malaikat menjawab: “Belum, demi Allah, mereka belum pernah melihat Engkau.” Allah bertanya lagi: “Bagaimana seandainya mereka pernah melihat-Ku?” Para malaikat menjawab : “Seandainya mereka pernah melihat Engkau, tentu mereka akan lebih giat lagi dalam beribadah, lebih giat lagi dalam mengagungkan Engkau dan memuji Engkau, dan lebih banyak lagi mensucikan Engkau”. Allah bertanya lagi: “Lalu apa yang mereka minta kepada-Ku?” Para malaikat menjawab: “Mereka meminta surga kepada Engkau.” Allah bertanya lagi: 'Apakah mereka pernah melihat surga-Ku?” Para malaikat menjawab: “Belum pernah. Demi Allah, wahai tuhanku, mereka belum pernah melihatnya.” Allah bertanya lagi: 'Bagaimana seandainya mereka itu pernah melihatnya?” Para malaikat menjawab: “Seandainya mereka pernah melihat surga, tentu mereka akan lebih berkeinginan lagi dalam meminta surga itu dan lebih besar lagi mengharapkannya.” Allah bertanya lagi: “Lalu mereka mohon perlindungan dari apa?” Para malaikat menjawab: “Mereka mohon perlindungan dari neraka.” Allah bertanya lagi: “Apakah mereka itu pernah melihat neraka?” Para malaikat menjawab: 'Belum pernah. Demi Allah, mereka belum pernah melihat neraka.” Allah bertanya lagi: ”Bagaimana seandainya mereka itu pernah melihat neraka?” Para malaikat menjawab: “Seandainya mereka itu pernah melihat neraka, tentu mereka lebih lari menjauh dan", 9], ["p", "lebih takut lagi.” Lalu Allah berfirman: “Aku persaksikan kepada kalian, bahwasanya Aku telah mengampuni mereka.” Lalu salah satu diantara malaikat itu berkata: “Ada si fulan yang bukan dari mereka itu tetapi ia datang untuk suatu keperluan (ini bagaimana)? Allah berfirman “ Mereka itu adalah suatu kaum yang tidak akan celaka orang yang ikut duduk di majlis mereka.” (HR. Bukhari juz 7 hal 168)", 10], ["a", "عَن ْ اَب هُرَي ِْرَة َ قَالَ: قَال َ رَسُوْل ُ للا ملسو هيلع هللا ىلص: مَن ْ كَفَّس َ عَن ْ مُؤْمِنٍ كُرْبَة ً ِْ مِن ْ كُرَب ِ الدُّكْيَا كَفَّس َ للا ُ عَن ْ ُ كُرْبَة ً مِن ْ كُرَب ِ ي َْوْم ِ اْلقِيَامَةِ، وَمَن يَعَّر َ عَلَى مُدْعِر ٍ يَعَّر َ للا ُ عَلَي ْ ِ ِفِ الدُّك ِْيَا وَا َْلٓخِرَة. وَمَن ْ سَرت ََ مُعْلِمًا سَرتََه ُ للا ُ ِفِ الدُّكْيَا وَا َْلٓخِرَةِ. وَللا ُ ِفِْ عَوْن ِ اْلدَبْد ِ مَا كَان َ الْدَبْد ِِْف ُ عَوْن ِ اَخِي ْ ِ. وَمَن ْ سَل ََْ طَرِيْقًا يَلْتَمِس ُ فِي ْ ِ عِلْمًا سَهَّل َ للا ُ ل َ ُ ب ِ ِ", 10], ["a", "طَرِيْقًا ا َِلَ ا ْْلَنَّةِ. وَمَا اجْت َم ق ََََوْم ِفِْ ب ٌَيْت ٍ مِن ْ بُيُوْت ِ للا ِ يَت َْلُوْن كِتَاب َ للا ِ وَيَتَدَارَسُوْك َ ُ بَيْنَهُم ْ ا َِلَّ كَزَلَت ْ عَلَيْهِم ُ العَّكِيْنَة ُ وَغَوِيَت ُْهُم الر َّْحَْة ُ وَحَفَّتْهُم ُ الْم ًَلَئِكَة ُ وَذَكَرَهُم ُ للا ُ فِيْمَن ْ عِنْدَهُ. وَمَن ْ بَطَّأ َ ب ِ ِ", 10], ["a", "38 رقم 2074 :4 معلم .ُ ُ ِع ْ ب ِ ِ كَعَبعَمَل ُ ُ لَ م ْ يُعْر", 10], ["p", "Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda : \"Barangsiapa menolong orang mukmin satu kesusahan dari kesusahan-kesusahannya di dunia, maka Allah akan menghilangkan baginya satu kesusahan dari kesusahan-kesusahannya pada hari qiyamat. Barangsiapa yang memberi kemudahan kepada orang yang dalam kesulitan, maka Allah akan memberinya kemudahan di dunia dan di akherat. Barangsiapa yang menutupi aib (cela) orang muslim,", 10], ["p", "maka Allah akan menutupi celanya di dunia dan di akherat. Dan Allah senantiasa menolong hamba-Nya selama hamba itu senang menolong saudaranya. Barangsiapa menempuh jalan untuk mencari ilmu, maka Allah akan memudahkan baginya jalan ke surga. Dan tidaklah suatu kaum berkumpul di dalam suatu masjid dari masjid-masjid Allah, mereka membaca dan mempelajari Al-Qur'an, melainkan turunlah ketenangan jiwa, rahmat menyelimuti mereka, para malaikat menaungi mereka, dan Allah menyebut-nyebut mereka dihadapan para malaikat yang berada di sisi-Nya. Dan barangsiapa yang malas beramal, maka tidaklah bermanfaat kemuliaan nasabnya\". [HR. Muslim juz 4, hal. 2074 no 38]", 11], ["a", "عَن ْ اَب ْ وَاقِد ِ اللَّيْث ِِ اَن َّ رَسُوْل َ للا ملسو هيلع هللا ىلص بَيْنَمَا هُو َ جَالِس ٌِ ِفِ الْمَعْجِد وَالنَّاس ُ مَد َ ُ، اِذ ْ اَقْبَل َ ث ًَلَثَة ُ كَفَرٍ، فَاَقْبَل َ اثْنَان ِ ا َِِلَ رَسُوْل ِ للا ملسو هيلع هللا ىلص ، وَذَهَب َ وَاحِدٌ. قَالَ: فَوَق َِفَا عَلَى رَسُوْل ِ للا ملسو هيلع هللا ىلص، فَاَمَّا اَحَد ُُهَُا فَرَأَى", 11], ["a", "فُرْجَة ً ِفِ اْلَلْقَة ِ فَجَلَس َ فِيْهَا، وَاَمَّا ا َْلٓخَر ُ فَجَلَس َ خَلْفَهُمْ، وَاَمَّا الثَّالِث ُ فَاَدْبَر َ ذَاهِبًا. فَلَمَّا فَر َِغ َ رَسُوْل ُ للا ملسو هيلع هللا ىلص قَالَ: ا ََلَ اُخْف ُِ كُم ْ عَن ِ النَّفَر ِ الث ًَّلَثَةِ؟ اَمَّا اَحَدُهُم ْ فَا َوَى ا َُِلَ للا ِ فَآوَاه ُ للاُ. وَاَمَّا ا َْلٓخَر فَاسْتَحْيَا فَاسْتَحْيَا للا ُ تَدَا َلَ مِن ْ ُ. وَاَمَّا ا َْلٓخَر ُ فَاَعْرَض َ فَاَعْرَض َ للاُ 24 :1 البخارى .ُ ْ عَن", 11], ["p", "Dari Abu Waqid Al-Laitsiy, ia berkata : \"Pada suatu waktu Rasulullah SAW sedang duduk di masjid bersama orang banyak, tiba tiba datang tiga orang. Yang dua orang langsung maju menghadap Rasulullah SAW, sedangkan yang seorang lagi berpaling lalu pergi. Lalu dua orang tersebut berhenti pada majlis Rasulullah SAW. Adapun salah satu", 11], ["p", "diantaranya melihat tempat yang masih longgar di dalam majlis tersebut, kemudian ia duduk padanya. Dan yang satunya lagi duduk di belakang mereka. Sedangkan orang yang ketiga langsung berpaling lalu pergi. Setelah selesai, kemudian Rasulullah SAW bersabda : \"Maukah aku beritahukan kepada kalian tentang tiga orang tadi? Adapun yang satu orang, ia mencari keridlaan Allah, maka Allah-pun ridla kepadanya. Yang satunya lagi, ia malu kepada Allah, maka Allah Ta’aalaa-pun malu kepadanya. Sedangkan yang satunya lagi, ia berpaling, maka Allah pun berpaling pula darinya\". [HR. Bukhari juz 1, hal. 24]", 12], ["a", "عَن ْ ا َِبِ مُوْسَى ا َْلَشْدَرِي رَض ِ َ للا ُ عَن ْ ُ قَالَ: قَال َ الن َُِِّّب ملسو هيلع هللا ىلص :مَثَلُ الَّذِى يَذْكُر ُ رَب ُ و َ الَّذِى َلَ يَذْكُر ُ مَثَل ُ اْل َو َ ال ْمَي ِتِ. البخارى 7 : 168", 12], ["p", "Dari Abu Musa Al-Asy’ariy RA , ia berkata : Nabi SAW bersabda : “Perumpamaan orang yang dzikir kepada Tuhannya dengan orang yang tidak berdzikir , bagaikan perbedaan antara orang yang hidup dengan orang yang mati”. [HR. Bukhari juz 7 , hal 168 ]", 12], ["a", "عَن ْ عَبْد ِ للا ِ بْن ِ بُعْر ٍ اَن َّ رَج ًُلً قَالَ: ِٰيَ رَسُوْل َ للاِ، اِن َّ شَرَائ ََِ ا َْلِس ًْلَم قَدْ كَثُرَت ْ عَل َ َّ فَاَخْفََن ِْ بِو َ ْء ٍ اَتَوَبَّث ُ ب ِ ِ؟ قَالَ: َلَ يَزَال ُ لِعَاك َُْ ، هذا حديث حعن غريب 3435 رقم 126 : 5 الرتمذى رَطْبًا مِن ْ ذِكْر ِ للاِ. من هذا الوج", 12], ["p", "Dari 'Abdullah bin Busr , ia berkata : Ada seorang bertanya kepada Rasulullah SAW : “Ya Rasulullah, sesungguhnya syari’at-syari’at Islam itu sangat banyak (amal kebaikannya), maka ajarkanlah kepada saya sesuatu yang akan saya pegang baik-baik”. Nabi SAW bersabda: “Hendaklah lidahmu selalu basah dengan dzikir kepada Allah”. [HR. Tirmidzi juz : 5 , hal 126 , no.3435 , ini hadits hasan gharib dari sisi ini]", 12], ["p", "Bersambung", 12]], "id": "p20260927-2278", "path": "data/pdf/260927-Doa-dan-Dzikir-1.pdf", "localPath": "data/pdf/260927-Doa-dan-Dzikir-1.pdf"}, {"src": "PDF", "file": "261004-Doa-dan-Dzikir-2.pdf", "title": "Do’a dan Dzikir (2)", "date": "2026-10-04", "ahad": "Ahad, 4 Oktober 2026 / 22 Rabii’ul Aakhir 1448", "no": "2279/2319/IA", "pages": 8, "size": 255290, "uploadedAt": "2026-11-01T15:51:22.413Z", "v": 1, "blocks": [["p", "Ahad, 4 Oktober 2026 / 22 Rabii’ul Aakhir 1448", 1], ["p", "Brosur No.: 2279/2319/IA", 1], ["h", "DO’A DAN DZIKIR (2)", 1], ["h", "2. Keutamaan dzikir “Laa ilaaha illallooh”", 1], ["p", "Laa ilaaha illallooh bukan sekadar kalimat yang ringan di lisan, tetapi kalimat tauhid yang paling utama, dzikir yang paling utama, dan termasuk ucapan yang paling dicintai Allah. Di dalamnya terdapat nafyun dan itsbaat: laa ilaaha adalah nafyun, yaitu meniadakan seluruh sesembahan selain Allah, sedangkan illallaah adalah itsbaat, yaitu menetapkan bahwa hanya Allah yang berhak diibadahi. Karena itu, kalimat ini bukan hanya untuk diucapkan, tetapi untuk diyakini, dipahami, dan diwujudkan dalam kehidupan. Hendaknya Laa ilaaha illallooh hidup dalam hati, tercermin dalam ibadah dan akhlaq, serta menjadi kalimat yang senantiasa kita jaga hingga akhir hayat. Nabi Muhammad SAW bersabda:", 1], ["a", "عَن ْ اَِبي ْ هُرَي يْرَة َ قَالَ: قَال َ رَسُوْل ُ للا ملسو هيلع هللا ىلص : ا َْلْي ْيَْان ُ بيضْع ٌ وَسَبْعُوْن َ ياَو ْ بيضْع ٌ وَس تُّوْن َ شُعْبَةً، فَاَفْضَلُهَا ق َُوْل ْلَ ايلٰه َ ايْلا ا ّللُٰٰ، وَاَد َْنَهَا ايمَاطَة ُ ا ذَى عَني الطارييْقي ، وَال ييَاء ُ شُعْبَة ٌ من َ ا ْلي ْيَْاني. مسلم 1: ْ َْ َْْل 58 رقم 63", 1], ["p", "Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda : \"Iman itu ada tujuh puluh cabang lebih atau enam puluh cabang lebih. Yang paling utama ialah ucapan \"Laa ilaaha illallooh\" (Tidak ada Tuhan selain Allah), dan yang paling rendah ialah menyingkirkan gangguan", 1], ["p", "di jalan, dan malu adalah salah satu cabang dari iman.\" [HR. Muslim juz 1, hal. 63, no. 58]", 2], ["a", "عَن ْ اَِبي ْ هُرَي يْرَة َ قَالَ: قَال َ رَسُوْل ُ للا ملسو هيلع هللا ىلص : ا َْلْي ي ْيَْان ُ بيضْع ٌ وَس تُّوْن َ اَو ْ سَبْعُوْن َ َبََبً، اَد َْنَهَا ايمَاطَة ُ ا ذَى عَني الطارييْقي ، وَاَرْفَعُهَا ق َُوْل ْلَ َْْل ايلٰه َ ايْلا ا ّللُٰٰ، وَال ييَاء ُ شُعْبَة ٌ من َ ا ْلْي يْيَْان. ابن ماجه 1: 22، رقم: 57 َْ", 2], ["p", "Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda: \"Iman itu ada enam puluh cabang lebih atau tujuh puluh cabang lebih. Yang paling rendah adalah menyingkirkan gangguan dari jalan, dan yang paling tinggi ialah ucapan \"Laa ilaaha illallooh\" (Tidak ada Tuhan selain Allah), dan malu adalah salah satu cabang dari iman. \" [HR. Ibnu Majah juz 1, hal. 22, no. 57]", 2], ["a", "عَن ْ جَابيري بْن يي عَبْد ي للا قَالَ: َسَي يعْت ُ رَسُوْل َ للا ملسو هيلع هللا ىلص يَقُوْل ُ : اَفْضَل ُ ٰيالذ يكْر ْلَ ايلٰه َ ا ييْلا للا ُ و َ اَفْضَل ُ الدُّعَاء اَلَْمْد ُ ّللي ٰٰي. ابن ماجه 2 : 3800 رقم 1249", 2], ["p", "Dari Jaabir bin ‘Abdullah, ia berkata: “Aku mendengar Rasulullah SAW bersabda : “ Dzikir yang paling utama adalah ucapan \"Laa ilaaha illallooh” (Tidak ada Tuhan selain Allah) dan do’a yang paling utama adalah “Alhamdulillaah” (Surat Al Faatihah). [HR. Ibnu Majah juz 2, hal. 1249, no. 3800]", 2], ["a", "عَن ْ جَابيري بْن يي عَبْد ي للا قَالَ: َسَي يعْت ُ رَسُوْل َ للا ملسو هيلع هللا ىلص يَقُوْل ُ : اَفْضَل ُ ٰيالذ يكْر ْلَ ايلٰه َ ا ييْلا للا ُ و َ اَفْضَل ُ الدُّعَاء اَلَْمْد ُ ّللي ٰٰي. الرتمذى 5 : 13- رقم 3443 , هذا حديث حسن غريب", 2], ["p", "Dari Jaabir bin ‘Abdullah, ia berkata: “Aku mendengar Rasulullah SAW bersabda : “ Dzikir yang paling utama adalah ucapan \"Laa ilaaha illallooh” (Tidak ada Tuhan selain Allah) dan do’a yang paling utama adalah “Alhamdulillaah” (Surat Al Faatihah). [HR. Tirmidzi juz 5, hal. 130, no. 3443, ini hadits hasan gharib ]", 3], ["a", "عَن ْ َسَُرَة َ بْن يي جُنْدَب ٍ قَالَ: قَال َ رَسُوْل ُ للا ملسو هيلع هللا ىلص ي: اَحَب ُّ الْك ََلَم اي يَلَ للا اَرْبَع ٌ : يسُبْحَان َ للا، و َ الَْمْد ّللي ٰٰي، و ْلَ ايلٰه َ ايْلا ا ، و َ ّللُٰٰ َ ُ للا ُ اَك َْبَُ، ْلَ يَضُرُّك َ َبيَيٰيهينا بَدَأْتَ. مسلم 3 :1685 رقم 12", 3], ["p", "Dari Samurah bin Jundab, ia berkata : “Rasulullah SAW bersabda : “Ucapan yang paling disukai Allah itu ada empat. (yaitu) \"Subhaanallooh, wal hamdu lillaah, wa Laa ilaaha illallooh, walloohu akbar\" (Maha suci Allah, segala puji bagi Allah, tidak ada Tuhan selain Allah, dan Allah Maha Besar). Tidak mengapa kamu memulai membaca dari mana saja. [HR. Muslim juz 3, hal. 1685, no. 12].", 3], ["a", "عَن ْ اَِبي ْ هُرَي يْرَة َ قَالَ: قَال َ رَسُوْل ُ للا ملسو هيلع هللا ىلص : ْلََن ْ اَقُوْلَ: َسُبْحَان يللا، و َ الَْمْد ّللي ٰٰي و ْلَ ايلٰه َ ايْلا ا و َ للا ُ اَك اَحَب ُّ اي ِمياا طَلَعَت ْ َلَا ََُْب ّللُٰٰ َ ُ يعَلَيْه الشامْس. مسلم 4 : 2072 رقم 32 ُ", 3], ["p", "Dari Abu Hurairah, ia berkata : “Rasulullah SAW bersabda : “Sungguh aku membaca \"Subhaanalloohi wal-hamdu lillaah wa laa ilaaha illallooh walloohu akbar\", yang demikian itu lebih aku sukai daripada apa-apa yang disinari matahari (yaitu dunia).” [HR. Muslim juz 4, hal. 2072, no. 32]", 3], ["a", "عَن ْ اَِبي ْ سَعييْد ٍ ا ْلُْدْريي يٰي قَالَ: قَال َ رَسُوْل ُ للا ٰي ملسو هيلع هللا ىلص: لَقنُوْا مَو َْتَكُمْ: ْلَ ايلٰه َ ايْلا للاُ. مسلم 2 : 631 رقم 1", 4], ["p", "Dari Abu Sa’id Al-Khudriy, ia berkata : “Rasulullah SAW bersabda : “Talqinkanlah orang-orang yang akan mati diantara kalian dengan kalimat \"laa ilaaha illallooh”. [HR. Muslim juz 2, hal. 631, no. 1]", 4], ["a", "عَن ْ اَِبي ْ هُرَي يْرَة َ قَالَ: قَال َ رَسُوْل ُ للا ٰي ملسو هيلع هللا ىلص: لَقنُوْا مَو َْتَكُمْ: ْلَ ايلٰه َ 2 رقم 631 :2 . مسلم ُيْلا للاا", 4], ["p", "Dari Abu Hurairah, ia berkata : “Rasulullah SAW bersabda : “Talqinkanlah orang-orang yang akan mati diantara kalian dengan kalimat \"laa ilaaha illallooh.” [HR. Muslim juz 2, hal. 631, no. 2]", 4], ["a", "عَن ْ مُعَاذ ٍ بْن يي جَبَل ٍ قَالَ: قَال َ رَسُوْل ُ للا ي ملسو هيلع هللا ىلص: مَنْ كَان َ اٰخ ي رُ ك ََلَميه ْلَ ايلٰه َ ايْلا للا ُ دَخَل َ الناةَ. ابو داود 3 : 190، رقم: 3116 َْ", 4], ["p", "Dari Mu'adz bin Jabal, ia berkata : Rasulullah SAW bersabda : “Barangsiapa yang akhir ucapannya itu \"laa ilaaha illallooh\" , maka ia masuk surga\". [HR. Abu Dawud juz 3, hal. 190, no. 3116]", 4], ["a", "عَن ْ اَِبي ْ هُرَي يْرَة َ قَالَ: قَال َ رَسُوْل ُ للا ٰي ملسو هيلع هللا ىلص: لَقنُوْا مَو َْتَكُمْ: ْلَ ايلٰه َ ا ييْلا للاُ. فَا يناه ُ مَنْ كَان َ اٰخ رُ كَليمَتييه ْلَ ايلٰه َ ا ييْلا للا ُ ع ينْد َ الْمَوْت دَخَل َ الَناةَ، ي يَوْمًا من َ الداهْري وَاين ْ اَصَابَه ُ قَبْل َ ذٰليك َ مَا اَصَابَهُ. ابن حبان ْ 3004 ، رقم:272 :7", 4], ["p", "Dari Abu Hurairah, ia berkata : “Rasulullah SAW bersabda : “Talqinkanlah orang-orang yang akan mati diantara kalian dengan", 4], ["p", "kalimat \"laa ilaaha illallooh”, karena barangsiapa yang akhir ucapannya laa ilaaha illallooh ketika akan mati, ia masuk surga, satu hari itu (lebih bermanfaat) daripada sepanjang hidupnya, meskipun sebelumnya ia telah melakukan perbuatan apa saja.\" [HR. Ibnu Hibban juz 7, hal. 272, no. 3004]", 5], ["a", "عَني ابْن يي ش هَاب ٍ قَالَ: اَخ َْبََِني ْ سَعييْد ُ بْن ُ الْمُسَياب يي عَن ْ اَبييْه قَالَ: لَماا حَضَرَت ْ ا ََبَ طَالي يب ٍ الْوَفَاة ُ جَاءَه ُ رَسُوْل ُ للا ملسو هيلع هللا ىلص، ف يَوَجَد َ عنْدَه ُ ا يََبَ جَهْل ٍ وَعَبْد َ للا بْن َ اَِبي ْ اُمَياة َ بْني الْمُغي ي ْيَْة، فَقَال َ رَسُو يل ُ للا ملسو هيلع هللا ىلص: ْ َيَ عَمٰي، قُلْ: ْلَ ايلٰه َ ايْلا للاُ،كَلي يمَة ً اَشْهَد ُ لَك َ بيهَا ع ينْد َ للا. ف ََقَال اَب يُو ْ جَهْل ٍ وَعَبْد ُ للا بْن ُ اَِبي ْ اُمَياةَ: َيَ ا طَاليبٍ، اَت يَرْغَب ُ عَن ْ م يلاة َََب يعَبْد الْمُطاليبي ؟ فَلَم ْ ي يَزَل ْ رَسُوْل ُ للا ملسو هيلع هللا ىلص يَعر ييضُهَا عَلَيْه وَيُعييْد ُ لَه ُ ْ تيلْك َ الْمَقَالَةَ، حََّتا قَال َ اَبُو ْ طَالي يب ٍ آخ ر َ مَا كَلامَهُمْ: هُو َ عَلَى يم يلاة ي عَبْد الْمُطاليبي ، وَا ََبَ اَن ْ يَقُوْلَ: ْلَ ايلٰه َ ايْلا للاُ. ف َُقَال َ رَسُوْل يللا ي ملسو هيلع هللا ىلص: اَمَا وَللا، ْلََسْت يَغْفرَنا لَك مَا لَ م ْ اُنْه َ عَنْكَ. فَاَنْزَل َ للا ُ َ عَزا وَجَلا: مَاكَان َ ليلناب ييٰي وَالاذيْن َ اٰمَنُوْآ اَن ْ ياسْت يَغْفرُوْا لي يلْمُشْركي ْيَْ وَلَو ْ كَانُوْآ اُوَلي ْ قُر يَْبٰ من ْ ب يَعْد مَا تَبَْيا يَ لَ هُم ْ اََّناُم ْ اَصْحٰب ُ الَْح ي يْم (التوبة: 113)، وَاَنْزَل َ للا ُ تَعَا َلَ ِفي ْ اَِبي ْ طَاليبٍ، فَقَال َ ليرَسُوْل يي للا", 5], ["a", "ملسو هيلع هللا ىلص: ايناك يَ ْلَ تَ هْدي ْ مَن ْ اَحْب يَبْت َ وَلٰكنا للا َ ي يَهْدي ْ مَن ْ ياشَآءُ، يوَهُو َ اَعْلَم ُ َبيلْمُهْتَديْنَ. مسلم 1: 54 رقم 39", 6], ["p", "Dari Ibnu Syihab, ia berkata : Telah mengkhabarkan kepadaku Sa’id bin Al-Musayyab dari ayahnya, ia berkata : \"Ketika Abu Thalib menjelang sakaratul maut, Rasulullah SAW menjenguknya. Beliau mendapati Abu Jahal dan Abdullah bin Abu Umayyah bin Al-Mughirah sudah berada di dekatnya. Rasulullah SAW bersabda : \"Wahai paman, ucapkanlah “laa ilaaha illallooh” kalimat yang dengannya aku menjadi saksi untukmu di hadapan Allah”. Lalu Abu Jahal dan Abdullah bin Abu Umayyah berkata, 'Wahai Abu Thalib, apakah kamu benci kepada agama 'Abdul Muththalib ?”. Rasulullah SAW tidak henti-hentinya menganjurkan supaya mengucap “laa ilaaha illallooh” dan beliau mengulang-ulang kalimat itu, sehingga Abu Thalib mengatakan sebagai ucapan terakhir kepada mereka, bahwa dia tetap pada agama Abdul Muththalib, dan enggan mengucapkan “laa ilaaha illallooh”. Kemudian Rasulullah SAW bersabda: \"Demi Allah, sungguh aku akan memohonkan ampun (kepada Allah) untukmu selama aku belum dilarang”. Kemudian Allah ‘Azza wa Jalla menurunkan ayat, maa kaana linnabiyyi walladdziina aamanuu ayyastaghfiruu lilmusyrikiina walau kaanuu ulii qurbaa min ba’di maa tabayyana lahum annahum ashhaabul jahiim“ (Tidak pantas bagi Nabi dan orang-orang yang beriman memintakan ampun (kepada Allah) bagi orang-orang musyrik walaupun orang-orang musyrik itu kaum kerabatnya setelah nyata bagi mereka bahwa orang-orang musyrik itu adalah penghuni neraka Jahiim)”. (QS. At-Taubah : 113). Dan Allah Ta’aalaa menurunkan ayat berkenaan dengan peristiwa Abu Thalib, Allah berfirman kepada Rasulullah SAW.\"innaka laa tahdii man ahbabta walaakinnallooha yahdii mayyasyaa’u wa huwa a’lamu bilmuhtadiin\" (Sesungguhnya kamu tidak dapat memberi petunjuk kepada orang yang kamu kasihi, tetapi Allah memberi petunjuk kepada orang yang dikehendaki-Nya, dan Allah lebih mengetahui orang-orang yang mau menerima petunjuk).” (QS. Al-Qashash : 56). [HR. Muslim juz 1, hal. 54, no. 39]", 6], ["a", "عَني ابْن يي ش هَاب ٍ قَالَ: اَخ َْبََِني ْ سَعييْد ُ بْن ُ الْمُسَياب يي عَن ْ اَبييْه قَالَ: لَماا حَضَر َ ا ََبَ طَالي يب ٍ الْوَفَاة ُ جَاء َ رَسُوْل ُ للا ملسو هيلع هللا ىلص ف يَوَجَد َ عنْدَه ُ ا َََب يجَهْل ٍ وَعَبْد َ للا بْن َ اَِبي ْ اُمَياة َ بْني الْمُغي ي ْيَْة، ف يَقَال َ رَسُوْل ُ للا ملسو هيلع هللا ىلص: َيَ عَمٰي، قُلْ: ْلَ ايلٰه َ ا ييْلا للاُ، اَشْهَد ُ لَك َ بيهَا ع ينْد َ للا. قَال َ اَبُو ْ يجَهْل ٍ وَعَبْد ُ للا بْن ُ اَِبي ْ اُمَياةَ: َيَ ا ََبَ طَاليبٍ، اَت يَرْغَب ُ عَن ْ م يلاة ي عَبْد الْمُطاليبي ؟ قَالَ: فَلَم ْ يَزَل يي الناب ُّ ملسو هيلع هللا ىلص يَعْريضُهَا عَل َ ييْه وَيُعييْد ُ لَه ُ تيلْك َ الْمَقَالَةَ، حََّتا قَال َ اَبُو ْ طَالي يب ٍ آخ ر َ مَا يكَلامَهُم ْ هُو َ عَلَى م يلاة ي عَبْد الْمُطاليبي وَا ََبَ اَن ْ يَقُوْلَ: ْلَ ايلٰه َ ايْلا للاُ. ف يَقَال َ رَسُوْل ُ للا ملسو هيلع هللا ىلص: ْلََسْت يَغْفرَنا لَك َ مَا َلَْ اُنْه َ عَنْكَ. فَا َنْزَل َ للاُ: مَا كَان َ ليلناب ييٰي وَالاذيْن َ اٰمَنُوْآ اَن ْ ياسْت يَغْفرُوْا لي يلْمُشْركي ْيَْ وَلَو ْ كَانُوْآ اُوَلي ْ قُر يَْبٰ من ْ ب يَعْد مَا تَبَْيا يلَ هُم ْ اَناهُم ْ اَصْحٰب ُ الَْح يْمي. (التوبة: 113), وَاُنْزيلَت ْ ِفي ْ اَِبي ْ َ طَاليبٍ: ايناك يَ ْلَ تَ هْدي ْ مَن ْ اَحْب يَبْت َ وَلٰكنا للا َ ي يَهْدي ْ مَن ْ ياشَآءُ، 982 ، رقم:262 :3 ابن حبان. )56 (القصص: يْنَ.وَهُو َ اَعْلَم ُ َبيلْمُهْتَدي", 7], ["p", "Dari Ibnu Syihab, ia berkata : Telah mengkhabarkan kepadaku Sa’id bin Al-Musayyab dari ayahnya, ia berkata : \"Ketika Abu Thalib menjelang sakaratul maut, Rasulullah SAW menjenguknya. Beliau mendapati Abu Jahal dan Abdullah bin Abu Umayyah bin Al-Mughirah sudah berada di dekatnya. Rasulullah SAW bersabda :\"Wahai paman, ucapkanlah “laa ilaaha illallooh” kalimat yang dengannya aku menjadi saksi untukmu di hadapan Allah”. Lalu Abu Jahal dan Abdullah bin Abu Umayyah berkata, 'Wahai Abu Thalib, apakah kamu benci kepada agama Abdul Muththalib ?”. Nabi SAW tidak henti-hentinya menganjurkan supaya mengucap “laa ilaaha illallooh” dan beliau mengulang-ulang kalimat itu, sehingga Abu Thalib mengatakan sebagai ucapan terakhir kepada mereka, bahwa dia tetap pada agama 'Abdul Muththalib, dan enggan mengucapkan “laa ilaaha illallooh”. Kemudian Rasulullah SAW bersabda : \"(Demi Allah), sungguh aku akan memohonkan ampun (kepada Allah) untukmu selama aku belum dilarang”. Kemudian Allah ‘menurunkan ayat, \"maa kaana linnabiyyi walladdziina aamanuu ayyastaghfiruu lilmusyrikiina walau kaanuu ulii qurbaa min ba’di maa tabayyana lahum annahum ashhaabul jahiim“ (Tidak pantas bagi Nabi dan orang-orang yang beriman memintakan ampun (kepada Allah) bagi orang-orang musyrik walaupun orang-orang musyrik itu kaum kerabatnya setelah nyata bagi mereka bahwa orang-orang musyrik itu adalah penghuni neraka Jahiim)”. (QS. At-Taubah : 113). Lalu diturunkan ayat berkenaan dengan peristiwa Abu Thalib ayat \"innaka laa tahdii man ahbabta walaakinnallooha yahdii mayyasyaa'u wa huwa a'lamu bilmuhtadiin\". (Sesungguhnya kamu tidak dapat memberi petunjuk kepada orang yang kamu kasihi, tetapi Allah memberi petunjuk kepada orang yang dikehendaki-Nya, dan Allah lebih mengetahui orang-orang yang mau menerima petunjuk)”. (QS. Al-Qashash : 56). [HR. Ibnu Hibbaan juz 3, hal. 262, no. 982]", 8], ["p", "Bersambung", 8]], "id": "p20261004-2279", "path": "data/pdf/261004-Doa-dan-Dzikir-2.pdf", "localPath": "data/pdf/261004-Doa-dan-Dzikir-2.pdf"}, {"src": "PDF", "file": "261011-Doa-dan-Dzikir-3_1.pdf", "title": "Do’a dan Dzikir (3)", "date": "2026-10-11", "ahad": "Ahad, 11 Oktober 2026 / 29 Rabii’ul Aakhir 1448", "no": "2280/2320/IF", "pages": 8, "size": 298376, "uploadedAt": "2026-11-01T15:51:22.413Z", "v": 1, "blocks": [["p", "Ahad, 11 Oktober 2026 / 29 Rabii’ul Aakhir 1448", 1], ["p", "Brosur No.: 2280/2320/IF", 1], ["h", "DO’A DAN DZIKIR (3)", 1], ["p", "3. Keutamaan \"Laa ilaaha illalloohu wahdahu laa syariikalah, lahul mulku wa lahul hamdu wa huwa ‘alaa kulli syai in qodiir\"", 1], ["a", "عَن ْ اَِبي ْ هُرَيْرَة َ عَن ْ رَسُوْل يي هللا ملسو هيلع هللا ىلص : مَن ْ سَبَّح َ هللا َ ِفي ْ دُبُر يي كُل ص ََلَة ٍ ث ََلًَثا وَث ََلَثي ْيَْ، و ََحَيد َ هللا َ ث ََلًَثا وَث ََلَثيْيَْ، و َك ََّبََّ هللا َ ث ََلًَثا وَث ََلَثي ْيَْ، فَتيلْك َ تيسْعَة ٌ وَتيسْعُوْنَ. وَقَال َ َتََام َ الْم ييائَة َلا اِلٰها اَِلا هللا ُ وحْداه ُ َلا شارِيْكا لاهُ، لاه ُ الْمُلْك ُ ولاه ُ اْحلامْد ُ وهُو عالاىكُل ِ ش ٍايْء ا ا ا ا قادِيْر ي, غُفرَت ْ خَطَا َيَه ُ وَاي ين ْ كَانَت ْ م يثْل َ زَبَد ال ْبَحْري.مسلم 1: 418 146 رقم", 1], ["p", "Dari Abu Hurairah, dari Rasulullah SAW, beliau bersabda: “Barangsiapa yang setiap habis shalat membaca tasbih sebanyak tiga puluh tiga kali, tahmid sebanyak tiga puluh tiga kali, takbir sebanyak tiga puluh tiga kali, yang demikian itu berarti sembilan puluh sembilan kali”. Nabi SAW bersabda: “Dan genap seratusnya ia mengucap Laa ilaaha illalloohu wahdahu laa syariika lah, lahul mulku wa lahul hamdu, wa huwa ‘alaa kulli syai-in qodiir (Tidak ada Tuhan selain", 1], ["p", "Allah yang Maha Esa, tiada sekutu bagi-Nya, bagi-Nya segala kerajaan dan bagi-Nya segala puji, dan Dia Maha Kuasa atas segala sesuatu), niscaya diampuni dosa-dosanya sekalipun sebanyak buih di laut”. [HR. Muslim juz 1, hal. 418, no. 146]", 2], ["a", "عَن ْ وَرَّاد ٍ كَاتيبي الْمُغي ي ْيَْة بْني شُعْبَة َ قَالَ: اَمْلَى عَلَي َّ الْمُغي ْيَْة ُ بْن ُ شُعْبَة َ ِفي ْ كيتَاب ٍ اي َلَ مُعَاوييَةَ، اَن َّ النَِّبي َّ ملسو هيلع هللا ىلصكَان َ يَقُوْل ُ ِفي ْ دُبُر يي كُل ص ََلَة ٍ مَكْت ٍُوْبَة َلا اِلٰها اَِلا هللا ُ وحْداه ُ َلا شارِيْكا لاهُ، لاه ُ الْمُلْك ُ ا او الاه ُ احلْامْد ُ و اهُو عالاى كُل ِ شايْء ٍ قادِيْر. االلٰهُما َلا ام اانِع ا لِما ااعْطايْتا ، و ااَلا مُعْطِي ا لِم اا مناعْتا ، واَلا يانْفاع ُ ذاا ا ْلْاد ِ مِنْكا ا ْلْاد. 205 :1 البخارى", 2], ["p", "Dari Warraad juru tulisnya Al-Mughirah bin Syu’bah, ia berkata: \"Al-Mughirah bin Syu’bah mendiktekan kepadaku untuk menulis surat yang akan dikirim kepada Mu’awiyah, bahwasanya dahulu Nabi SAW sesudah shalat wajib, beliau membacaa : \"Laa ilaaha illalloohu wahdahu laa syariika lah, lahul mulku wa lahul hamdu, wa huwa ‘alaa kulli syai-in qodiir. Alloohumma laa maani’a limaa a’thoita, wa laa mu’thiya limaa mana’ta, wa laa yanfa’u dzal jaddi minkal jaddu. (Tidak ada Tuhan selain Allah yang Maha Esa, tidak ada sekutu bagi-Nya, bagi-Nya segala kerajaan, dan bagi-Nya segala puji, dan Dia Maha Kuasa atas segala sesuatu. Ya Allah, tidak ada yang bisa menghalangi terhadap apa yang Engkau berikan, dan tidak ada yang bisa memberi terhadap apa yang Engkau halangi, dan tidaklah bermanfaat orang yang mempunyai kekayaan, dari Engkaulah kekayaan itu”. [HR. Bukhari juz 1, hal. 205]", 2], ["a", "عَن ْ اَِبي الزُّب َْيْي قَال َ :كَان َ ابْن ُ الزُّب َْيْي يَقُوْل ُ ِفي ْ دُبُري كُل يي ص ََلَة ٍ ح ْيَْ", 2], ["a", "يُسَلي: ُ مَلا اِلٰها اَِلا هللا ُ وحْداه ُ َلا شارِيْكا لاهُ، لاه ُ الْمُلْك ُ ولاه ُ اْحلامْد ا ا ُ وهُو عالاى كُل ِ شايْء ٍ قادِي اْر. َلا حوْلا واَلا قُواةا اَِلا ِبِهللِ، َلا اِلٰها ا ا اَِلا هللاُ، و ااَلا ناعْبُد ُ اَِلا اَِّياهُ، لاه ُ النِعْم اة ُ ولاه ُ ال ْف ااضْلُ، ولاه ُ الثانااء ُ احلْاسنُ. َلا اِلٰها اَِلا هللا ُ ُمُْلِص ِْيْا لاه ُ الد ِيْن ولاو ْ كارِها ا ا ا ْالك ااافِرُوْن. يوَقَال َ : كَان َ رَسُوْل ُ هللا ملسو هيلع هللا ىلص يُهَليل ُ ِبيين َّ دُب يُر َ كُل", 3], ["a", "139 رقم 415 : 1 مسلم ص ََلَةٍ.", 3], ["p", "Dari Abuz Zubair, ia berkata : \"Dahulu Ibnuz Zubair setiap sesudah shalat (wajib), yaitu sesudah salam, membaca :“Laa ilaaha illalloohu wahdahu laa syariikalah, lahul mulku wa lahul hamdu, wa huwa ‘alaa kulli syai-in qodiir. Laa haula wa laa quwwata illaa billaah, laa ilaaha illallooh, wa laa na’budu illaa iyyaah, lahun ni’matu wa lahul fadllu, wa lahuts tsanaa-ul hasan. Laa ilaaha illalloohu mukhlishiina lahud-diina walau karihal kaafiruun” (Tidak ada Tuhan selain Allah Yang Maha Esa, tidak ada sekutu bagi-Nya, bagi-Nya segala kerajaan, dan bagi-Nya segala puji, dan Dia Maha Kuasa atas segala sesuatu. Tidak ada daya dan tidak ada kekuatan kecuali dengan pertolongan Allah. Tidak ada Tuhan selain Allah, kami tidak menyembah kecuali hanya kepada-Nya, bagi-Nya segala keni’matan, bagi-Nya segala keutamaan, dan bagi-Nya segala sanjungan yang baik. Tidak ada Tuhan selain Allah, kami menjalankan agama ini setulusnya kepada-Nya, walaupun orang-orang kafir membencinya)”. Dan (Ibnuz Zubair) berkata : “Dahulu Rasulullah SAW mengucapkan demikian setiap sesudah shalat (wajib)”. [HR. Muslim juz 1, hal. 415, no. 139]", 3], ["a", "عَن ْ اَِبي يْ ذَر ٍ اَن َّ رَسُوْل َ هللا ملسو هيلع هللا ىلص قَال َ : مَن ْ قَال َ ِفي ْ دُبُر يي ص ََلَة الْفَجْري وَهُو َ ًثَن ٍ ر ييجْلَيْه قَبْل َ اَن ْ يَتَكَلَّم : َلا اِلٰها اَِلا ا ّلل ُٰ وحْداه ُ َلا ا َ شارِيْك اا لاه ُ ، لاه ُ الْمُلْك ُ ولاه ُ احلْامْد اُ ُيُْيِي ْ و اُيُِيْت ُ ، و اهُو عالاى كُل ِ شايْء ٍ قادِيْر . عَشْر َ مَرَّات ٍ ، كُتيبَت ْ لَه ُ عَشْر ُ حَسَنَاتٍ، و َُمُييَت ْ عَنْه ُ عَشْر ُ سَييئَات ٍ ، وَرُفيع َ لَه ُ عَشْر ُ دَرَجَات ٍ ، وَكَان َ يَوْمَه ُ ذٰليك َ كُلَّه ُ ِفي يح ي رْز ٍ من ْ كُلي مَكْرُوه ٍ ، وَحُر ييس َ من الشَّيْطَاني ، و َََْل َ يَنْبَغي لي يذَنْب ٍ اَن ْ يُدْركَه ُ ِفي ْ ذٰليك َ الْي يَوْم اي يَّلَّ الش ي رْك َ ِبيهلل. الرتمذى 5 : 1٧٧ رقم 3541 ، هذا حديث حسن صحيح غريب", 4], ["p", "Dari Abu Dzarr , bahwasanya Rasulullah SAW bersabda : \"Barang siapa setelah shalat Shubuh dan ia masih melipat kedua kakinya sebelum ia berbicara (dengan orang orang), ia membaca : \"Laa ilaaha illalloohu wahdahu laa syariika lah , lahul mulku wa lahul hamdu yuhyii wa yumiit , wahuwa 'alaa kulli syai in qodiir \" (Tidak ada Tuhan selain Allah yang Maha Esa , tidak ada sekutu bagiNya, bagiNya semua kerajaan dan bagiNya seluruh pujian, Dia Yang menghidupkan dan yang mematikan, dan Dia Maha Kuasa atas segala sesuatu) sepuluh kali, maka dicatat baginya sepuluh kebaikan dan dihapus darinya sepuluh kesalahan dan diangkat baginya sepuluh derajat, dan pada hari itu ia berada dalam perlindungan dari segala yang tidak disukai, dan terjaga dari syetan, dan tidak layak ada dosa yang mendapatinya pada hari itu kecuali syirik kepada Allah\". [ HR. Tirmidzi juz : 5 , hal. 177 , no.3541 , ini hadits hasan shahih gharib ]", 4], ["a", "عَن ْ اَِبي ْ ايسْحَاقَ، عَن ْ عَمْريو بْني مَيْمُون ٍ قَالَ: مَن ْ قَالَ: َلا اِلٰها ْ اَِلا ا اّلل ُٰ وحْداه ُ َلا شارِيْكا لاه ُ ، لاه ُ ال ْ امُلْك ُ و لاه ُ احلْا امْد ُ و ا هُو عالاىكُل ِ شايْء ٍ قادِيْر ي، عَشْر َ مرَارٍ،كَانَ كَمَن ْ اَعْتَق َ اَرْبَعَة َ اَن ٍْفُس يم ين ْ وَلَد اي ي ْسَْاعيْلَ. مسلم 4 : 20٧1 رقم 30", 5], ["p", "Dari Abu Ishaq, dari 'Amr bin Maimun, ia berkata : “Barangsiapa membaca \"Laa ilaaha illalloohu wahdahu laa syariika lah, lahul mulku wa lahul hamdu wa huwa ‘alaa kulli syai-in qodiir\" (Tidak ada Tuhan selain Allah Yang Maha Esa, tidak ada sekutu bagi-Nya, bagi-Nya segala kerajaan dan bagi-Nya segala puji, dan Dia Maha Kuasa atas segala sesuatu), sepuluh kali, maka ia mendapatkan pahala seperti orang yang memerdekakan empat orang budak dari keturunan Isma'il\". [HR. Muslim juz : 4 , hal 2071, no.30 ]", 5], ["a", "عَن ْ اَِبي ْ هُرَي يْرَة َ اَن َّ رَسُوْل َ هللا َ ملسو هيلع هللا ىلص قَالَ: مَن ْ قَال َلا اِلٰها اَِلا ا ُٰ ّلل اوحْداه ُ َلا شارِيْكا لاه ُ ، لاه ُ ال ْ امُلْك ُ و لاه ُ احلْا امْد ُ و ا هُو ع ِالاى كُل شايْء ٍ قادِيْر ، ِفي ي يَوْم ٍ مائَة َ مَرَّة ٍ ، كَانَت ْ لَه ُ عَدْل َ عَشْري ريقَابٍ. و َ كُتي يبَت ْ لَه ُ مائَة ُ حَسَنَةٍ، وُمُي َ ييَت ْ عَنْه ُ مائَة ُ سَييئَةٍ، و َ كَانَت ْ لَه ُ يح رْز ياا من َ الشَّيْطَاني يَوْمَه ُ ذٰليك َ ح ََّّت يُيُْس يَ، و يَلَْ َيَْت َ اَحَد ٌ اَفْضَل َ ِمي ي َّا جَاء َ بيه ايََّّل رَجُل ٌ عَميل َ اَكْث يَر َ منْهُ. البخارى ٧ : 16٧", 5], ["p", "Dari Abu Hurairah RA, ia berkata : Rasulullah SAW bersabda : “Barangsiapa membaca \"Laa ilaaha illalloohu wahdahu laa syariika", 5], ["p", "lah lahul mulku wa lahul hamdu wa huwa ‘alaa kulli syai-in qodiir\" (Tiada Tuhan selain Allah Yang Maha Esa, tiada sekutu bagi-Nya, bagi-Nya segala kerajaan dan bagi-Nya segala puji dan Dia Maha Kuasa atas segala sesuatu), dalam sehari seratus kali, maka ia seimbang dengan memiliki sepuluh budak, dan dicatat untuknya seratus kebaikan dan dihapus dari padanya seratus dosa dan ia terpelihara dari gangguan syaithan pada hari itu hingga sore hari. Dan tidak ada seorang yang lebih utama daripada amalnya kecuali orang yang berbuat lebih banyak dari pada dia\".[ HR.Bukhari juz 7, hal 167 ]", 6], ["a", "ِبي ي ْعَن ا َ ْ هُرَيْرَة َ اَن َّ رَسُوْل َ هللا َ ملسو هيلع هللا ىلصقَالَ: مَن ْ قَال :َلا اِلٰها اَِلا ا ّلل ُٰ اوحْداه ُ َلا شارِيْكا لاه ُ ، لاه ُ ال ْ امُلْك ُ و لاه ُ احلْا امْد ُ و ا هُو ع ِالاى كُل شايْء ٍ قادِيْر، ِفي ي يَوْم ٍ مائَة َ مَرَّة ٍ ، كَانَت ْ لَه ُ عَدْل َ عَشْري ريقَاب ٍ ، ْ وَكُتي يبَت ْ لَه ُ مائَة ُ حَسَنَة ٍ ، و َُمُي ييَت ْ عَنْه ُ مائَة ُ سَييئَة ٍ ، و يَكَانَت ْ لَه ُ ح رْزاا يمن َ الشَّيْطَاني يَوْمَه ُ ذٰليك َ ح يَّتَّ ُيُْسي َ ، و يََلَْ َيَْت اَحَد ٌ اَفْضَل َ ِمي َّا جَاء َ بييه اي َّلَّ اَحَد ٌ عَميل َ اَكْث يَر َ من ْ ذٰلي َكَ. وَمَن ْ قَال سُبْحان ِا هللا ا و ِمْدِه ِفي ْ ي يَوْم ٍ م يائَة َ مَرَّةٍ، حُطَّت ْ خَطَا َيَه ُ وَلَوْ كَانَت ْ م يثْل َ زَبَد ا ِبِا الْبَحْري. مسلم 4 : 20٧1 رقم 28", 6], ["p", "Dari Abu Hurairah, bahwasanya Rasulullah SAW bersabda : “Barangsiapa membaca \"Laa ilaaha illalloohu wahdahu laa syariika lah, lahul mulku wa lahul hamdu wa huwa ‘alaa kulli syai-in qodiir\" (Tidak ada Tuhan selain Allah Yang Maha Esa, tidak ada sekutu bagi-Nya, bagi-Nya segala kerajaan dan bagi-Nya segala puji, dan Dia Maha Kuasa atas segala sesuatu), dalam sehari seratus kali,", 6], ["p", "maka ia seimbang dengan memiliki sepuluh budak, dan dicatat untuknya seratus kebaikan , dan dihapus dari padanya seratus dosa , dan ia terpelihara dari gangguan syaithan pada hari itu hingga sore hari. Dan tidak ada seorang yang lebih utama daripada amalnya kecuali orang yang berbuat lebih banyak dari itu. Dan barangsiapa membaca :\"Subhaanalloohi wabihamdih\" (Maha Suci Allah dengan segala pujianNya) seratus kali dalam sehari, maka dihapus dosa dosanya walaupun dosa dosanya itu sebanyak buih di laut\". [HR. Muslim juz : 4 , hal. 2071 , no. 28]", 7], ["a", "عَن يْ َحََّاد بْني اَِبي ْ َحَُيْد ٍ ، عَن ْ عَمْريو بْن يي شُعَيْب ٍ ، عَن ْ اَبييْه عَن ْ يجَد يه اَن َّ النَِّبي َّ ملسو هيلع هللا ىلص قَال َ : خ يَْيُْ الدُّعَاء دُعَاء ُ ي يَوْم عَرَفَة َ وَخ َْيُْ مَا قُلْت ُ ا ََنَ وَالنَّبيي يُّوْن َ من ْ قَبْلييْ: َلا اِلٰها اَِلا ا ّلل ُٰ وحْداه ُ َلا شارِيْك ا ا لاه ُ ، لاه ُ الْ امُلْك ُ و لاه ُ احلْا امْد ُ و ا هُو عالاىكُل ِ شايْء ٍ قادِيْر. الرتمذى ْ َحَُيْد ٍ لَيْس َ هُوَ . هذا حديث حسن غريب ، َحََّاد ُ بْن ُ اَِبي 3655 رقم 231 : 5 ِبيلْقَويي يي عنْد َ اَهْل يي ا ْلَْد ييْث", 7], ["p", "Dari Hammaad bin Abu Humaid , dari 'Amr bin Syu'aib, dari ayahnya, dari kakeknya , bahwasanya Nabi SAW bersabda : \"Sebaik-baik do'a adalah do'a pada hari 'Arafah , dan sebaik-baik apa yang aku ucapkan dan diucapkan oleh para Nabi sebelumku adalah \"Laa ilaaha illalloohu wahdahu laa syariika lah lahul mulku walahul hamdu wa huwa 'alaa kulli syai in qodiir\" (Tidak ada Tuhan selain Allah yang Maha Esa tidak ada sekutu bagi-Nya, bagi Nya segala kerajaan dan bagiNya segala puji , dan Dia Maha Kuasa atas segala sesuatu).\" [ HR.Tirmidzi juz : 5 , hal 231 , no.3655 , ini hadits hasan ghorib, Hammaad bin Abi Humaid tidak kuat menurut ahli hadits ]", 7], ["p", "Dari berbagai hadits di atas, dapat disimpulkan bahwa kalimat “Laa ilaaha illalloohu waḥdahu laa syariika lahu lahul mulku walahul", 7], ["p", "hamdu wa huwa ‘alaa kulli syai in qodiir” merupakan dzikir yang sangat utama, karena mengandung pengakuan yang sempurna. Di antara keutamaannya adalah:", 8], ["p", "1. Mengandung inti tauhid, yaitu menetapkan bahwa hanya Allah yang berhak disembah dan tidak ada sekutu bagi-Nya.", 8], ["p", "2. Mendapat pahala yang sangat besar. Membacanya 100 kali dalam sehari disebutkan pahalanya seperti memerdekakan sepuluh budak, dicatat 100 kebaikan, dihapus 100 dosa, dan mendapat perlindungan dari gangguan setan hingga sore hari.", 8], ["p", "3. Menjadi sebab terhapusnya dosa, sebagaimana disebutkan dalam dzikir setelah shalat bersama tasbih, tahmid, dan takbir.", 8], ["p", "4. Menguatkan keyakinan bahwa seluruh kerajaan dan kekuasaan adalah milik Allah. Lahul-mulku mengajarkan bahwa apa pun yang dimiliki manusia pada hakikatnya berada dalam kekuasaan Allah.", 8], ["p", "5. Mengajarkan untuk memuji Allah dalam segala keadaan. Wa lahul-ḥamdu menunjukkan bahwa segala pujian yang sempurna adalah milik Allah.", 8], ["p", "6. Meneguhkan keyakinan terhadap kekuasaan Allah. Wa huwa ‘alaa kulli syai in qodiir berarti Allah Maha kuasa atas segala sesuatu.", 8], ["p", "7. Menjadi dzikir yang dituntunkan setelah shalat, sebagaimana dicontohkan oleh Rasulullah SAW.", 8], ["p", "8. Menjadi dzikir yang agung pada hari Arafah, sebagaimana disebutkan dalam hadits yang dinukil dari Nabi SAW.", 8], ["p", "Bersambung", 8]], "id": "p20261011-2280", "path": "data/pdf/261011-Doa-dan-Dzikir-3_1.pdf", "localPath": "data/pdf/261011-Doa-dan-Dzikir-3_1.pdf"}, {"src": "PDF", "file": "261025-Doa-dan-Dzikir-5.pdf", "title": "Do’a dan Dzikir (5)", "date": "2026-10-25", "ahad": "Ahad, 25 Oktober 2026 / 14 Jumaadal Uulaa 1448", "no": "2282/2322/IA", "pages": 8, "size": 264165, "uploadedAt": "2026-11-01T15:51:22.413Z", "v": 1, "blocks": [["p", "Ahad, 25 Oktober 2026 / 14 Jumaadal Uulaa 1448", 1], ["p", "Brosur No.: 2282/2322/IA", 1], ["h", "DO’A DAN DZIKIR (5)", 1], ["h", "5. Keutamaan Hauqolah (Laa haula walaa quwwata illaa billaah)", 1], ["p", "Laa haula walaa quwwata illaa billaah, kalimat ini disebut ḥauqolah. Kalimatnya pendek dan ringan diucapkan, tetapi mengandung makna tauhid yang sangat dalam. Di dalamnya terdapat pengakuan bahwa manusia adalah makhluk yang lemah, terbatas kemampuannya, dan selalu membutuhkan pertolongan Allah dalam menjalani kehidupan, melaksanakan ketaatan, menghadapi ujian, serta menjauhi kemaksiatan.", 1], ["p", "Kalimat “Laa haula walaa quwwata illaa billaah” bukan berarti manusia tidak perlu berusaha. Sebaliknya, seorang muslim tetap wajib berikhtiyar, bekerja, belajar, berdo’a, dan mengambil sebab-sebab yang dibenarkan oleh syariat. Setiap orang tidak boleh menyandarkan keberhasilan hanya kepada kecerdasan, kekuatan, kekayaan, jabatan, atau kemampuannya sendiri. Semua kemampuan itu merupakan karunia Allah, dan keberhasilan tidak akan terwujud kecuali dengan izin serta pertolongan-Nya. Oleh karena itu, Rasulullah SAW menyebut kalimat ini sebagai simpanan dari simpanan-simpanan surga.", 1], ["p", "Yang dimaksud dengan simpanan surga adalah kalimat dzikir yang memiliki keutamaan dan pahala yang sangat besar di sisi Allah, sehingga diibaratkan sebagai harta berharga yang disimpan untuk kehidupan akhirat. Sebagaimana manusia bersungguh-sungguh mengumpulkan kekayaan untuk menjamin kehidupan dunianya,", 1], ["p", "seorang muslim hendaknya juga bersungguh-sungguh mengumpulkan bekal akhirat melalui iman, ibadah, amal shaleh, dan dzikir kepada Allah.", 2], ["p", "Makna setiap bagian kalimat", 2], ["p", "a.وْلا َلا حا — Laa haula", 2], ["p", "Artinya, tidak ada daya atau kemampuan untuk berubah dari satu keadaan menuju keadaan yang lain kecuali dengan pertolongan Allah. Manusia tidak mampu sepenuhnya mengendalikan dirinya, keadaan sekelilingnya, ataupun seluruh perjalanan hidupnya.", 2], ["p", "Seseorang mungkin mengetahui bahwa shalat itu wajib, tetapi untuk istiqamah mengerjakannya ia membutuhkan pertolongan Allah. Seseorang mungkin ingin meninggalkan maksiat, tetapi untuk melawan hawa nafsu dan kebiasaan buruk ia membutuhkan pertolongan Allah. Seseorang mungkin ingin bersabar menghadapi musibah, tetapi keteguhan hati juga merupakan karunia Allah.", 2], ["p", "b. ُوَّةاَلا قوا — wa laa quwwata", 2], ["p", "Artinya, tidak ada kekuatan yang hakiki dan mandiri yang dapat diandalkan tanpa pertolongan Allah. Manusia memang diberi tenaga, akal, ilmu, kesehatan, harta, dan kemampuan untuk berusaha. Akan tetapi, semua itu terbatas, dapat berkurang, bahkan dapat hilang sewaktu-waktu.", 2], ["p", "Kekuatan fisik tidak menjamin seseorang selalu sehat. Kecerdasan tidak menjamin seseorang selalu benar. Kekayaan tidak menjamin seseorang selalu bahagia. Jabatan tidak menjamin seseorang mampu menyelesaikan semua persoalan. Karena itu, orang beriman tidak boleh sombong ketika memiliki kemampuan dan tidak boleh berputus asa ketika menghadapi keterbatasan.", 2], ["p", "c.َلَّ ِب لل ا — illaa billaah", 2], ["p", "Artinya, kecuali dengan Allah, yakni dengan pertolongan, taufiq, dan izin-Nya. Inilah inti penghambaan seorang muslim: ia berusaha", 2], ["p", "menggunakan seluruh kemampuan yang Allah berikan, tetapi hatinya tetap bergantung kepada Allah.", 3], ["p", "Dengan demikian, kalimat ini mengajarkan dua sikap yang harus berjalan bersama: berusaha dengan sungguh-sungguh dan bertawakkal kepada Allah. Tidak benar jika seseorang hanya berserah diri tanpa berusaha. Tidak benar pula jika seseorang merasa bahwa seluruh keberhasilannya semata-mata hasil kemampuannya sendiri. Ayat Al-Qur’an yang mendukung makna “Laa Ḥaula wa Laa Quwwata illaa Billaah”", 3], ["a", "ولاوَْلا ٓ اذ ْ دخلْت جنَّتاكا قُلْت ما شااۤء الل ۙ َلا قُوَّةا ا َّٰلَّ ِب لل ۚ ان ا ا ا ا ا ا ا ا ُّٰ ْ ۚ اتارن ااَنا ۠ ااقال َّ م نْك اا م ااَلا وَّولاداا . الكهف : 39", 3], ["p", "Mengapa ketika engkau memasuki kebunmu tidak mengucapkan, “Maa syaa Allaah, laa quwwata illaa billaah” (sungguh, ini semua kehendak Allah. Tidak ada kekuatan apa pun kecuali dengan [pertolongan] Allah). Jika engkau anggap harta dan keturunanku lebih sedikit daripadamu. [QS. Al Kahfi : 39]", 3], ["p", "Penjelasan ayat : Ketika seseorang melihat kebun yang subur, kekayaan yang melimpah, usaha yang berhasil, atau kedudukan yang tinggi, ia tidak boleh merasa bahwa semuanya semata-mata hasil kecerdasan dan kekuatannya sendiri. Ia harus menyadari bahwa kemampuan bekerja, kesehatan, kesempatan, dan hasil yang diperoleh merupakan bagian dari karunia Allah.", 3], ["p", "Ayat ini juga mengingatkan bahwa kekayaan dapat menjadi ujian. Orang yang memahami makna laa quwwata illaa billaah tidak akan menggunakan hartanya untuk menyombongkan diri, merendahkan orang lain, atau berbuat maksiat. Sebaliknya, ia akan semakin bersyukur, semakin taat, dan semakin berhati-hati dalam menggunakan nikmat Allah.", 3], ["p", "Hadits-hadits Nabi SAW :", 4], ["a", "عن ااب مُوسى اا ْلْاشْع اري ّقاال: ااخذا الن ملسو هيلع هللا ىلص ف عقاب ٍة اا او ْ قاال ا ْ ْ ا ا ا ُّ َِّب ْ ا ا ْف ثان يَّة ٍ .قاالا : فالامَّا ع ااَلا علاياْه اا ر اجُل ٌ َناد اى فار افاع ا صوْتاهُ َلا الها ا اَلا هللا ُ و هللاُ ااكَْبا ُ . قاال اا وارسُول ُ هللا ملسو هيلع هللا ىلص اعلاى باغْلاته: اقاال فاا ْنَّكُم ْ َلا تادْعُوان اا اص ام َّ وَلا غاائ باا. ُثَُّ قاالا : َيا ااِبا ْ مُواسى ، ااو ْ َيا اعبْدا هللا ، ااَلا اادُلُّك اا علاى ك االمة ٍ من ْ كانْز ا ْلْانَّة؟ قُلْت ُ : بالاى. اقاال : َلا احوْلا واَلا قُواةا اَلا ِب لل. البخارى 7 : 169", 4], ["p", "Dari Abu Musa Al Asy'ariy, ia berkata : \"Nabi SAW pernah lewat di jalan menanjak atau di tempat yang tinggi . Abu Musa berkata : \"Ketika jalan menanjak ada seorang laki laki yang menyeru dengan suara keras \"Laa ilaaha illallooh walloohu akbar\" ( Tidak ada Tuhan selain Allah dan Allah Maha Besar ). Lalu Rasulullah SAW bersabda sedangkan beliau diatas bagholnya : \"Sesungguhnya kalian tidaklah menyeru kepada yang tuli dan tidak pula yang jauh\". Abu Musa berkata : “Kemudian Rasulullah SAW bersabda : \"Hai Abu Musa, atau beliau bersabda: \"Hai 'Abdullah, maukah aku tunjukkan kepadamu suatu kalimat dari simpanan surga ?\" Aku menjawab : \"Ya , mau.\" Beliau bersabda : \"Laa haula walaa quwwata illaa billaah\". [ HR. Bukhari juz 7, hal. 169 ]", 4], ["a", "اع ْن اا ْب ْمُواس اى ا ْلْاشْعري ّقاالا : لامَّا غااز اا ر ْسُو ُل هللا ملسو هيلع هللا ىلص اخ اايْب ، اا ْو قاال اا لامَّا تاوجَّها ا ر ْسُول ُ هللا ملسو هيلع هللا ىلص اا اشْرف اا النَّاس ُ ع الاى و ااد ٍ فار ْفاعُوا", 4], ["a", "اا اصْواَتا ُم ْْ ِب لتَّكْبي هللاُ ااكَْبا ُ هللاُ ااكَْبا ُ َلا الها اَلا هللا ُ فاقاال اا ر ْسُو ُل هللا ملسو هيلع هللا ىلص: ارْبا ْعُو اا علاى اان ْْفُس كُم ا ْنَّكُم ْ َلا تادْعُوان اا اص ام َّ وَلا غاائ باا ا ْنَّكُم ْ تادْعُون ْا َسا ياعا قاريبا اا و اهُو ا ماع اكُم ْ واا اَنا خ الْف ا د اابَّة ر ْسُول هللا ملسو هيلع هللا ىلص فاسمعن وااَنا ااقُو ُل اَلا حوْلا واَلا قُواةا اَلا ِب لل. فاقاالا ل: ا ا ْ ا ْ ْ َيا اعبْد اا هللا بْن قايْس ٍ . قُلْت ُ : لابَّيْكا َيا ا ر ْسُولا هللا . قاالا : ااَلا اا ادُلُّك اعلاى ك االمة ٍ من ْ كانْز ٍ من ْ كُن ُْوز ا ْلْانَّة ؟ قُلْت ُ : بالاى َيا ا ر ْسُوال هللا فاد اااك ااب وا ُمّ ي ا. قاال : اَلا حوْلا واَلا قُواةا اَلا ِب لل .البخارى 5 : 75 ْ ا ْ", 5], ["p", "Dari Abu Musa Al Asy'ariy, ia berkata : \" Ketika Rasulullah SAW perang melawan (penduduk) Khaibar, atau ia berkata : \"Ketika Rasulullah SAW melihat orang-orang menuruni lembah sambil meninggikan suara dengan bertakbir, Alloohu Akbar, Alloohu Akbar laa ilaaha illallooh (Allah Maha Besar, Allah Maha Besar, tidak ada Tuhan selain Allah), maka Rasulullah SAW bersabda: \"Kasihanilah diri kalian, karena sesungguhnya kalian tidak menyeru kepada yang tuli dan tidak pula yang jauh. Sesungguhnya kalian menyeru kepada Tuhan yang Maha Mendengar lagi Maha Dekat dan Dia selalu bersama kalian\". Saat itu aku berada di belakang hewan tunggangan Rasulullah SAW dan beliau mendengar apa yang aku ucapkan. Saat itu aku membaca \"laa haula wa laa quwwata illaa billaah\" (Tidak ada daya dan kekuatan melainkan dengan pertolongan Allah), maka beliau bersabda kepadaku: \"Hai Abdullah bin Qais\". Aku menjawab : \"Aku penuhi panggilanmu wahai Rasulullah.\" Beliau bersabda : \"Maukah aku tunjukkan kepadamu suatu kalimat dari simpanan dari simpanan simpanan surga?\". Aku menjawab : \"Mau ya Rasulullah,", 5], ["p", "kutebusi engkau dengan ayah dan ibuku \". Beliau bersabda : \"laa haula walaa quwwata illaa billaah\". [ HR. Bukhari juz : 5 , hal 75 ]", 6], ["a", "اع ْن اا ْب ْمُواسى قاال اا : كُنَّا ماع الن ملسو هيلع هللا ىلص ْف اسف اار ٍ فاجاع ال ُ النَّاس ّ َِّب اَيا ْه ْرُوان ِْب لتَّكْبي . فاقاالا الن ُّ َِّب ملسو هيلع هللا ىلص : ااياُّها النَّاس ُ ارْبا ْعُو اا علاى اان ْْفُس كُم انَّكُم ْ لايْس ْ تادْعُوان اا اص ام َّ وَلا غاائ باا ا ْنَّكُم ْ تادْعُون ْا َسا ياعا ا قاري ْبا اا و اهُو ا ماعكُم ْ . قاال اا واا اَنا خ الْفه ُ اوااَنا ااق ُْو: ُ ل اَلا حوْلا واَلا قُواةا اَلا ِب لل . فاقاالا : ا عبْدا هللا بْن ٍ قايْس ااَلا اادُلُّك اا علاى كانْز ٍ من َيا ا ْ كُن ُْوز ا ْلْانَّة ؟ فاقُلْت ُ : بالاى َيا ا رسُولا هللا . قاال ْا : قُل ا\"َلا ح اوْل واَلا قُواةا اَلا ِب لل \". مسلم 4 : 2076 رقم 44", 6], ["p", "Dari Abu Musa , ia berkata : \"Dahulu kami pernah bepergian bersama Nabi SAW , lalu orang orang bertakbir dengan suara keras , maka Nabi SAW bersabda : \"Hai para manusia, kasihanilah diri kalian ! Sesungguhnya kalian tidak menyeru kepada yang tuli dan tidak pula kepada yang jauh. Sesungguhnya kalian menyeru kepada Tuhan yang Maha Mendengar, Maha dekat, dan Dia bersama kalian\". Abu Musa berkata : \" Pada waktu itu aku berada di belakang beliau, dan pada waktu itu aku membaca \"Laa haula walaa quwwata illaa billaah \"(Tidak ada daya dan kekuatan melainkan dengan pertolongan Allah). Lalu beliau bersabda : \" Hal 'Abdullah bin Qois , maukah aku tunjukkan kepadamu suatu simpanan dari simpanan simpanan surga ? Aku menjawawab : \"Mau, ya Rasulullah\". Beliau bersabda : Ucapkanlah “Laa haula walaa quwwata illaa billaah\". [HR. Muslim juz 4 , hal. 2076, no. 44 ]", 6], ["a", "اع ْن اا ْب امُوسى اا َّنَُّمْ كاان ُْو اا ماع ا ر ْسُول هللا ملسو هيلع هللا ىلص اوهُم ْ يا اصْع ْدُون ْا ف ثان يَّة ٍ . قاال اا فاجاع ال ا ر اجُلٌ كُلَّما ع ااَلا ثان يَّةا َنادى َلا الها ا اَلا هللا ُ وهللا ُ ااكَْبا ُ. قاالا فاقاالا نا ِب ُّ هللا ملسو هيلع هللا ىلص : انَّكُم ْ َلا ت ُْناادُوان اا اص ام َّ وَلا غاائباا. قاالا فاقاالا : َيا ااِبا ْ مُواسى ااو ْ َيا ا عبْدا هللا بْن ٍ قايْس، ااَلا اادُلُّك اا علاى ا ك االمة ٍ من ْ كانْز ا ْلْانَّة ؟ ق اُلْت ُ : ما ه يا َيا ا ر ْسُولا هللا ؟ قاالا : َلا احوْلا واَلا قُواةا اَلا ِب لل . مسلم 4 : 2077, رقم 45", 7], ["p", "Dari Abu Musa, ia mengatakan bahwasanya dahulu para shahabat pernah bepergian bersama Rasulullah SAW, pada waktu itu mereka sedang berjalan naik menanjak pada tempat yang tinggi. Abu Musa berkata : “Lalu ada seorang laki laki setiap naik pada tempat (jalan) yang tinggi ia menyeru dengan suara keras \"Laa ilaaha illallooh walloohu akbar\" ( Tidak ada Tuhan selain Allah dan Allah Maha Besar). Abu Musa berkata : “Maka Nabiyyullah SAW bersabda : \"Sesungguhnya kalian tidaklah menyeru kepada yang tuli dan tidak pula yang jauh\". Abu Musa berkata : “Lalu Rasulullah SAW bersabda : \"Hai Abu Musa, atau beliau bersabda \"Hai 'Abdullah bin Qois, maukah aku tunjukkan kepadamu suatu kalimat dari simpanan surga?\" Aku menjawab : \"Kalimat apa itu ya Rasulullah ?\" Beliau bersabda : \"Laa haula walaa quwwata illaa billaah.\" [ HR. Muslim juz : 4 , hal. 2077, no.45]", 7], ["a", "اع ْن اا ْب امُوس اى ا ْلْاشْعري ّقاالا : قاال ْا ل ار ْسُول ُ هللا ملسو هيلع هللا ىلص : ااَلا اادُلُّك اا علاىك االمة ٍ منْ كُن ُْوز ا ْلْانَّة ااو ْ قاال اا علاىكانْز ٍ منْ كُنُوز ا ْلْانَّة؟", 7], ["a", "فاقُلْت ُ : بلاى . فاقاالا : اَلا حوْلا واَلا قُواةا اَلا ِبلل .مسلم 4 : ا 47 , رقم2078", 8], ["p", "Dari Abu Musa Al Asy'ariy, ia berkata : \" Rasulullah SAW bersabda kepadaku : \" Maukah aku tunjukkan kepadamu suatu kalimat dari simpanan simpanan surga ? Atau beliau bersabda : \" Maukah aku tunjukkan kepadamu suatu simpanan dari simpanan simpanan surga ?\" Maka aku menjawab : \"Ya, mau.\" Lalu beliau bersabda : \" Laa haula walaa quwwata illaa billaah.\" [HR. Muslim juz : 4 , hal. 2078, no. 47]", 8], ["a", "اع ْن اقايْس بْن سعْد بْن عُبا اادةا اا َّن ااِبا ا ه ُ د افاعهُ اَلا الن ملسو هيلع هللا ىلص َيا ْدُمُهُ. ّ َِّب قاال اا : فام ار َّ ب الن ُّ َِّب ملسو هيلع هللا ىلص او اقاد ْ صلَّيْتُ، فاضااربا ْن ابرجْله وقاالا : ااَلا اادُلُّك اا علاى ِبا ْ ب ٍ من ااباْواب ا ْلْانَّة؟ قُلْت ُ : بالاى. قاالا : َلا اح اوْل واَلا قُواةا اَلا ِب لل. الرتمذى : 5 , 230 رقم 5652 ,هذا حديث حسن صحيح", 8], ["p", "Dari Qais bin Sa'ad bin 'Ubaadah, bahwasanya ayahnya menyerahkannya kepada Nabi SAW supaya membantu beliau. Ia bekata : \"Pada suatu ketika Nabi SAW menghampiriku, pada waktu itu aku habis shalat. Beliau menyentuhku dengan kaki beliau lalu bersabda : \"Maukah aku tunjukkan kepadamu suatu pintu dari pintu pintu surga?\" Aku menjawab : \"Mau.\" Beliau bersabda : \"Laa haula wa laa quwwata illaa billaah\". ( Tidak ada daya dan kekuatan kecuali dengan pertolongan Allah )\". [HR. Tirmidzi juz 5 , hal. 230, no. 5652, ini hadits hasan shahih]", 8], ["p", "Bersambung", 8]], "id": "p20261025-2282", "path": "data/pdf/261025-Doa-dan-Dzikir-5.pdf", "localPath": "data/pdf/261025-Doa-dan-Dzikir-5.pdf"}];